Lemma PfTab_of_XImg : forall m, XImg m -> PfTab m.
Proof.
  intros m XI. unfold PfTab, PF_TABPTR, PF_TAB.
  pose proof (chunk_of_XImg m (0x84ce8, [0x15c9e]) XI ltac:(vm_compute; reflexivity)) as C. cbn [fst snd wcells map] in C. exact C.
Qed.

Lemma MiscVt48_of_XImg : forall m, XImg m -> MiscVt48 m.
Proof.
  intros m XI. unfold MiscVt48, VP_MISC_ECAT, P_ECAT_FAILED.
  pose proof (chunk_of_XImg m (0x7e6a8 + 48, [0x2cb68]) XI ltac:(vm_compute; reflexivity)) as C. cbn [fst snd wcells map] in C.
  exact (ro_cell0 _ _ _ _ C).
Qed.

Lemma pcore_init_ok : pcore_ok pcore_init.
Proof. unfold pcore_ok, pcore_init, FL_EAGER. cbn. repeat split; try lia; cbn; qtauto. Qed.

